def double_result(func):
    def wrapper(*args,**kwargs):
        return 2*func(*args,**kwargs)
    return wrapper
@double_result
def multiply(a,b):
    return a*b
a,b=map(int,input().split())
print(multiply(a,b))

def even_numbers(start,end):
    for n in range(start,end):
        if n%2==0:
            yield n
start,end=map(int,input().split())
values=list(even_numbers(start,end))
print(*values) if values else print("NONE")

from collections import defaultdict
from decimal import Decimal,ROUND_HALF_UP
from fractions import Fraction
q=int(input())
grades={}
for _ in range(q):
    parts=input().split()
    if parts[0]=="ADD":
        grades[parts[1]]=[]
    else:
        grades[parts[1]].append(int(parts[2]))
if not grades:
    print("NONE")
else:
    def exact_average(values):
        return Fraction(sum(values),len(values)) if values else Fraction(0,1)
    for name,values in sorted(grades.items(),key=lambda item:(-exact_average(item[1]),item[0])):
        avg=(Decimal(sum(values))/Decimal(len(values))) if values else Decimal(0)
        print(name,avg.quantize(Decimal("0.01"),rounding=ROUND_HALF_UP))
